import { cloudflareTest } from "@cloudflare/vitest-pool-workers";
import { defineConfig } from "vitest/config";

export default defineConfig({
  plugins: [
    cloudflareTest({
      wrangler: { configPath: "./wrangler.jsonc" },
    }),
  ],
  test: {
    include: ["test/**/*.spec.ts"],
  },
});

declare module "cloudflare:workers" {
  interface ProvidedEnv extends Env {}
}

import { describe, expect, it } from "vitest";

import { generateSecMsGec, hashSecMsGecPayload } from "../src/lib/sec-ms-gec";

const TRUSTED_CLIENT_TOKEN = "[REDACTED]";

// Expected values come from edge-tts 7.3.x `generate_sec_ms_gec_v2`
// (rany2/edge-tts ba61d944), whose tokens the service accepts.
describe("generateSecMsGec", () => {
  it.each([
    [
      0,
      "52BC7A17B50DFEC9-28C4394775C8751CD2F6859C030C06DB1489ACAB3B3A7651831FC26895177ED6",
    ],
    [
      1700000000,
      "2CD23A2CA0B2595A-F3C846C370E05F9CC83ACC5F995C5F5D87A4D0F14CE8936A0F902E64099E38A2",
    ],
    [
      1760600000.5,
      "382DA39AE9C7234A-D592F521358E457AC9556722046D878B004105AEE12B81167D37FD4778D35E78",
    ],
    [
      1792134000,
      "CF0B4395B2CD4BA5-EC6B89FFC22DF1DBD6A58EF3BC4A5F778F76C002BD63C080F0A4104A5FAEC52B",
    ],
    [
      2000000000,
      "2D62557F1142BC5D-FD9C30C68FF194A5EE6B45FEFC5E2BA1D1239F88A90569AB55CFFFAA7799F40E",
    ],
  ])("matches the reference token at %s", (unixSeconds, expected) => {
    expect(generateSecMsGec(TRUSTED_CLIENT_TOKEN, unixSeconds)).toBe(expected);
  });

  it("keeps the token for a five-minute window", () => {
    const token = [REDACTED], 1792134000);

    expect(generateSecMsGec(TRUSTED_CLIENT_TOKEN, 1792134299.9)).toBe(token);
    expect(generateSecMsGec(TRUSTED_CLIENT_TOKEN, 1792134300)).not.toBe(token);
  });
});

describe("hashSecMsGecPayload", () => {
  it.each([
    [
      "1234567",
      "CF8264F204E37578-4B4B1B27BCB09F84AE904B387373DA006A64E1B4EFCC1BAF1D6F289D44E6DAC8",
    ],
    [
      "12345678",
      "FF68734F9C22A4D6-F7CC197E8281C6E3B1AE9BC5214DFF71C9E86469BCFAA2DABD23507CDA13FC63",
    ],
    [
      "x".repeat(55),
      "996577B3641023D6-05A53DDF994DCE366C6ED80548479F12ECF745F579F815913817D28CBE6E34FE",
    ],
    [
      "y".repeat(56),
      "2A0B6457A67319DA-78F668C7076B12D2D0E2F88FB482EB7C287923EDFA932EA8BBB67A8B60FF8D97",
    ],
    [
      "z".repeat(63),
      "BC12C68945A0583B-E9C75AD567FB678DE4365DC1C924FA5B518A0B02A21D388B33B9D62F74C9092B",
    ],
    [
      "w".repeat(64),
      "C0D297350783A55E-A0E1576CC8374BF56BB38AD0275E85DD93A4C1969200DFAE859C7D14C74E7E5F",
    ],
    [
      "v".repeat(130),
      "E287CC0106D6B526-C059029B109D097EABB34794ABBB179A6D37BC429515FE7111EE64BF933970C7",
    ],
  ])("matches the reference hash for payload %#", (payload, expected) => {
    expect(hashSecMsGecPayload(payload)).toBe(expected);
  });

  it("rejects payloads shorter than seven bytes", () => {
    expect(() => hashSecMsGecPayload("123456")).toThrow(
      "Sec-MS-GEC payload must contain at least seven bytes"
    );
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";

import {
  DEFAULT_VOICE,
  createAudioStream,
  getVoices,
  type TtsRuntime,
} from "../src/lib/tts";

const SEC_MS_GEC_V2_PATTERN = /^[0-9A-F]{16}-[0-9A-F]{64}$/;

function createRuntime(fetchImpl: TtsRuntime["fetch"]): TtsRuntime {
  return {
    fetch: fetchImpl,
    crypto: {
      getRandomValues: vi.fn((array: Uint8Array) => {
        for (let index = 0; index < array.length; index += 1) {
          array[index] = (index + 17) & 0xff;
        }
        return array;
      }),
      randomUUID: vi.fn(
        () => "12345678-90ab-4def-8123-4567890abcde"
      ),
    } as unknown as Crypto,
  };
}

class FakeWebSocket {
  accepted = false;
  sent: Array<string | ArrayBufferLike | Blob | ArrayBufferView> = [];
  private listeners = new Map<string, Set<(event: unknown) => void>>();

  accept() {
    this.accepted = true;
  }

  addEventListener(type: string, listener: (event: unknown) => void) {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, new Set());
    }

    this.listeners.get(type)?.add(listener);
  }

  removeEventListener(type: string, listener: (event: unknown) => void) {
    this.listeners.get(type)?.delete(listener);
  }

  send(data: string | ArrayBufferLike | Blob | ArrayBufferView) {
    this.sent.push(data);
  }

  close() {
    this.emit("close", {});
  }

  emitMessage(data: unknown) {
    this.emit("message", { data });
  }

  emitError(error: unknown) {
    this.emit("error", error);
  }

  private emit(type: string, event: unknown) {
    for (const listener of this.listeners.get(type) ?? []) {
      listener(event);
    }
  }
}

function createAudioFrame(bytes: number[]) {
  const headerText = "Path:audio\r\nContent-Type:audio/mpeg\r\n";
  const headerBytes = new TextEncoder().encode(headerText);
  const frame = new Uint8Array(2 + headerBytes.length + bytes.length);

  frame[0] = (headerBytes.length >> 8) & 0xff;
  frame[1] = headerBytes.length & 0xff;
  frame.set(headerBytes, 2);
  frame.set(bytes, 2 + headerBytes.length);

  return frame.buffer;
}

async function readAll(stream: ReadableStream<Uint8Array>) {
  const reader = stream.getReader();
  const chunks: Uint8Array[] = [];

  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }

    chunks.push(value);
  }

  const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const merged = new Uint8Array(totalLength);
  let offset = 0;

  for (const chunk of chunks) {
    merged.set(chunk, offset);
    offset += chunk.length;
  }

  return merged;
}

describe("createAudioStream", () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it("opens a websocket upgrade request and streams audio chunks for the default voice", async () => {
    const socket = new FakeWebSocket();
    const fetchMock = vi.fn().mockResolvedValue({
      status: 101,
      headers: new Headers({
        Upgrade: "websocket",
      }),
      webSocket: socket,
    });
    const runtime = createRuntime(fetchMock);

    const stream = await createAudioStream({ text: "hello world" }, runtime);

    expect(fetchMock).toHaveBeenCalledTimes(1);
    const [url, init] = fetchMock.mock.calls[0] ?? [];
    expect(String(url)).toContain(
      "https://speech.platform.bing.com/consumer/speech/synthesize/readaloud/edge/v1"
    );
    const searchParams = new URL(String(url)).searchParams;
    expect(searchParams.get("TrustedClientToken")).toBe(
      "6A5AA1D4EAFF4E9FB37E23D68491D6F4"
    );
    expect(searchParams.get("Sec-MS-GEC")).toMatch(SEC_MS_GEC_V2_PATTERN);
    expect(searchParams.get("Sec-MS-GEC-Version")).toBe("2-143.0.3650.75");
    expect(searchParams.get("ConnectionId")).toBe(
      "1234567890ab4def81234567890abcde"
    );
    expect(init?.headers).toMatchObject({
      Upgrade: "websocket",
      "Sec-WebSocket-Version": "13",
    });
    expect((init?.headers as Record<string, string>).Origin).toBeUndefined();
    expect(String((init?.headers as Record<string, string>).Cookie)).toContain(
      "muid="
    );
    expect(socket.accepted).toBe(true);
    expect(socket.sent).toHaveLength(2);
    expect(String(socket.sent[0])).toContain("Path:speech.config");
    expect(String(socket.sent[1])).toContain("Path:ssml");
    expect(String(socket.sent[1])).toContain(
      "Microsoft Server Speech Text to Speech Voice (en-US, AvaMultilingualNeural)"
    );
    expect(String(socket.sent[1])).toContain("hello world");

    queueMicrotask(() => {
      socket.emitMessage(createAudioFrame([1, 2, 3]));
      socket.close();
    });

    const bytes = await readAll(stream);
    expect(Array.from(bytes)).toEqual([1, 2, 3]);
  });

  it("normalizes short voice names before sending ssml", async () => {
    const socket = new FakeWebSocket();
    const fetchMock = vi.fn().mockResolvedValue({
      status: 101,
      headers: new Headers({
        Upgrade: "websocket",
      }),
      webSocket: socket,
    });
    const runtime = createRuntime(fetchMock);

    const stream = await createAudioStream(
      {
        text: "hello world",
        voice: "en-US-EmmaMultilingualNeural",
      },
      runtime
    );

    queueMicrotask(() => {
      socket.emitMessage(createAudioFrame([9]));
      socket.close();
    });

    await readAll(stream);

    expect(String(socket.sent[1])).toContain(
      "Microsoft Server Speech Text to Speech Voice (en-US, EmmaMultilingualNeural)"
    );
  });

  it("maps provider voice aliases to a supported short voice", async () => {
    const socket = new FakeWebSocket();
    const fetchMock = vi.fn().mockResolvedValue({
      status: 101,
      headers: new Headers({
        Upgrade: "websocket",
      }),
      webSocket: socket,
    });
    const runtime = createRuntime(fetchMock);

    const stream = await createAudioStream(
      {
        text: "hello world",
        voice: "zh-CN-Xiaoxiao:DragonHDFlashLatestNeural",
      },
      runtime
    );

    queueMicrotask(() => {
      socket.emitMessage(createAudioFrame([7]));
      socket.close();
    });

    await readAll(stream);

    expect(String(socket.sent[1])).toContain(
      "Microsoft Server Speech Text to Speech Voice (zh-CN, XiaoxiaoNeural)"
    );
  });

  it("throws when the websocket upgrade is rejected", async () => {
    const runtime = createRuntime(
      vi.fn().mockResolvedValue({
        status: 403,
        headers: new Headers(),
      })
    );

    await expect(
      createAudioStream({ text: "hello world" }, runtime)
    ).rejects.toThrow("WebSocket upgrade failed with status 403");
  });
});

describe("getVoices", () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it("fetches the vendor voice list over http", async () => {
    const vendorVoices = [
      {
        Name: "Microsoft Server Speech Text to Speech Voice (zh-CN, XiaoxiaoNeural)",
        ShortName: "zh-CN-XiaoxiaoNeural",
        Gender: "Female",
        Locale: "zh-CN",
        SuggestedCodec: "audio-24khz-48kbitrate-mono-mp3",
        FriendlyName: "Microsoft Xiaoxiao Online (Natural) - Chinese (Mainland)",
        Status: "GA",
        VoiceTag: {
          ContentCategories: ["General"],
          VoicePersonalities: ["Friendly"],
        },
      },
    ];
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      status: 200,
      json: vi.fn().mockResolvedValue(vendorVoices),
      headers: new Headers(),
    });
    const runtime = createRuntime(fetchMock);

    const voices = await getVoices(runtime);

    expect(fetchMock).toHaveBeenCalledTimes(1);
    const [url, init] = fetchMock.mock.calls[0] ?? [];
    expect(String(url)).toContain(
      "https://speech.platform.bing.com/consumer/speech/synthesize/readaloud/voices/list"
    );
    const searchParams = new URL(String(url)).searchParams;
    expect(searchParams.get("trustedclienttoken")).toBe(
      "6A5AA1D4EAFF4E9FB37E23D68491D6F4"
    );
    expect(searchParams.get("Sec-MS-GEC")).toMatch(SEC_MS_GEC_V2_PATTERN);
    expect(searchParams.get("Sec-MS-GEC-Version")).toBe("2-143.0.3650.75");
    expect(init?.headers).toMatchObject({
      Accept: "*/*",
      "Sec-Fetch-Mode": "cors",
      "Sec-Fetch-Dest": "empty",
    });
    expect(voices).toBe(vendorVoices);
  });
});

/// <reference types="@cloudflare/vitest-pool-workers/types" />

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  createExecutionContext,
  waitOnExecutionContext,
} from "cloudflare:test";

const { getVoicesMock, createAudioStreamMock } = vi.hoisted(() => ({
  getVoicesMock: vi.fn(),
  createAudioStreamMock: vi.fn(),
}));

vi.mock("../src/lib/tts", () => ({
  DEFAULT_VOICE: "en-US-AvaMultilingualNeural",
  getVoices: getVoicesMock,
  createAudioStream: createAudioStreamMock,
}));

import worker from "../src/index";
import { handleTtsHealth } from "../src/handlers/tts-health";

const IncomingRequest = Request;

async function dispatch(request: Request) {
  const ctx = createExecutionContext();
  const response = await worker.fetch(request, {} as Env, ctx);
  await waitOnExecutionContext(ctx);
  return response;
}

const sampleVoices = [
  {
    Name: "Microsoft Server Speech Text to Speech Voice (zh-CN, XiaoxiaoNeural)",
    ShortName: "zh-CN-XiaoxiaoNeural",
    Gender: "Female",
    Locale: "zh-CN",
    SuggestedCodec: "audio-24khz-48kbitrate-mono-mp3",
    FriendlyName: "Microsoft Xiaoxiao Online (Natural) - Chinese (Mainland)",
    Status: "GA",
    VoiceTag: {
      ContentCategories: ["General"],
      VoicePersonalities: ["Friendly"],
    },
  },
];

describe("worker routes", () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });

  beforeEach(() => {
    vi.clearAllMocks();
    getVoicesMock.mockResolvedValue(sampleVoices);
    createAudioStreamMock.mockResolvedValue(
      new ReadableStream<Uint8Array>({
        start(controller) {
          controller.enqueue(new Uint8Array([1, 2, 3]));
          controller.close();
        },
      })
    );
  });

  it("returns health status", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/health")
    );

    expect(response.status).toBe(200);
    expect(await response.json()).toEqual({ ok: true });
    expect(response.headers.get("access-control-allow-origin")).toBe("*");
  });

  it("returns voices", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/voices")
    );

    expect(response.status).toBe(200);
    expect(await response.json()).toEqual({ voices: sampleVoices });
  });

  it("returns upstream error when voices fetch fails", async () => {
    const upstreamError = new Error("upstream failed");
    getVoicesMock.mockRejectedValueOnce(upstreamError);
    const consoleError = vi.spyOn(console, "error").mockImplementation(() => {});

    const response = await dispatch(
      new IncomingRequest("https://example.com/voices")
    );

    expect(response.status).toBe(502);
    expect(await response.json()).toEqual({
      error: {
        code: "TTS_UPSTREAM_ERROR",
        message: "failed to fetch voices",
      },
    });
    expect(consoleError).toHaveBeenCalledWith(
      "voice list fetch failed",
      upstreamError
    );
  });

  it("returns audio stream for valid tts requests", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          text: " hello world ",
        }),
      })
    );

    expect(response.status).toBe(200);
    expect(response.headers.get("content-type")).toBe("audio/mpeg");
    expect(createAudioStreamMock).toHaveBeenCalledWith({
      text: "hello world",
      voice: undefined,
    });
    expect(new Uint8Array(await response.arrayBuffer())).toEqual(
      new Uint8Array([1, 2, 3])
    );
  });

  it("forwards explicit voice for tts requests", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          text: "hello world",
          voice: "en-US-JennyNeural",
        }),
      })
    );

    expect(response.status).toBe(200);
    expect(createAudioStreamMock).toHaveBeenCalledWith({
      text: "hello world",
      voice: "en-US-JennyNeural",
    });
  });

  it("accepts application json with charset parameters", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json; charset=utf-8",
        },
        body: JSON.stringify({
          text: "hello world",
        }),
      })
    );

    expect(response.status).toBe(200);
    expect(response.headers.get("content-type")).toBe("audio/mpeg");
    expect(createAudioStreamMock).toHaveBeenCalledWith({
      text: "hello world",
      voice: undefined,
    });
  });

  it("rejects non-json tts requests", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "text/plain",
        },
        body: "hello world",
      })
    );

    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: {
        code: "INVALID_CONTENT_TYPE",
        message: "content-type must be application/json",
      },
    });
  });

  it("rejects json-like but invalid content types", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/jsonp",
        },
        body: JSON.stringify({
          text: "hello world",
        }),
      })
    );

    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: {
        code: "INVALID_CONTENT_TYPE",
        message: "content-type must be application/json",
      },
    });
  });

  it("rejects invalid json bodies with a stable error message", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: "{",
      })
    );

    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: {
        code: "INVALID_REQUEST",
        message: "request body must be valid json",
      },
    });
  });

  it("rejects tts requests with missing text", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({}),
      })
    );

    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: {
        code: "INVALID_REQUEST",
        message: "text is required",
      },
    });
  });

  it("rejects tts requests with non-string voice", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          text: "hello world",
          voice: 123,
        }),
      })
    );

    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: {
        code: "INVALID_REQUEST",
        message: "voice must be a string",
      },
    });
  });

  it("rejects tts requests with an empty voice string", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          text: "hello world",
          voice: "",
        }),
      })
    );

    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: {
        code: "INVALID_REQUEST",
        message: "voice must be a non-empty string",
      },
    });
  });

  it("returns upstream error when tts synthesis fails before streaming starts", async () => {
    const upstreamError = new Error("WebSocket upgrade failed with status 403");
    createAudioStreamMock.mockRejectedValueOnce(upstreamError);
    const consoleError = vi.spyOn(console, "error").mockImplementation(() => {});

    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          text: "hello world",
        }),
      })
    );

    expect(response.status).toBe(502);
    expect(await response.json()).toEqual({
      error: {
        code: "TTS_UPSTREAM_ERROR",
        message: "failed to synthesize audio",
      },
    });
    expect(consoleError).toHaveBeenCalledWith(
      "tts synthesis failed",
      upstreamError
    );
  });

  it("returns upstream error when the first audio chunk read fails", async () => {
    const streamError = new Error("stream failed");
    createAudioStreamMock.mockResolvedValueOnce(
      new ReadableStream<Uint8Array>({
        pull(controller) {
          controller.error(streamError);
        },
      })
    );
    const consoleError = vi.spyOn(console, "error").mockImplementation(() => {});

    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          text: "hello world",
        }),
      })
    );

    expect(response.status).toBe(502);
    expect(await response.json()).toEqual({
      error: {
        code: "TTS_UPSTREAM_ERROR",
        message: "failed to synthesize audio",
      },
    });
    expect(consoleError).toHaveBeenCalledWith(
      "tts synthesis failed",
      streamError
    );
  });

  it("answers CORS preflight requests", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/tts", {
        method: "OPTIONS",
        headers: {
          Origin: "https://app.example.com",
          "Access-Control-Request-Method": "POST",
        },
      })
    );

    expect(response.status).toBe(204);
    expect(response.headers.get("access-control-allow-origin")).toBe("*");
    expect(response.headers.get("access-control-allow-methods")).toContain("POST");
  });

  it("returns method not allowed for POST /health", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/health", {
        method: "POST",
      })
    );

    expect(response.status).toBe(405);
    expect(await response.json()).toEqual({
      error: {
        code: "METHOD_NOT_ALLOWED",
        message: "method not allowed",
      },
    });
  });

  it("returns not found for unknown routes", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/missing")
    );

    expect(response.status).toBe(404);
    expect(await response.json()).toEqual({
      error: {
        code: "NOT_FOUND",
        message: "route not found",
      },
    });
  });
});

function audioStream(...chunks: Uint8Array[]) {
  return new ReadableStream<Uint8Array>({
    start(controller) {
      for (const chunk of chunks) {
        controller.enqueue(chunk);
      }
      controller.close();
    },
  });
}

describe("tts health probe", () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });

  beforeEach(() => {
    vi.clearAllMocks();
    createAudioStreamMock.mockImplementation(async () =>
      audioStream(new Uint8Array([1, 2, 3]))
    );
  });

  it("synthesizes a short phrase with each default voice", async () => {
    const response = await dispatch(
      new IncomingRequest("https://example.com/health/tts")
    );

    expect(response.status).toBe(200);
