import { createAudioStream } from "../lib/tts";
import { CORS_HEADERS, errorResponse } from "../lib/http";

type TtsBody = {
  text?: unknown;
  voice?: unknown;
};

function isJsonContentType(value: string) {
  const mediaType = value.split(";")[0]?.trim().toLowerCase();
  return mediaType === "application/json";
}

function parseBody(body: unknown) {
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    throw new Error("request body must be an object");
  }

  const { text, voice } = body as TtsBody;

  if (typeof text !== "string" || text.trim().length === 0) {
    throw new Error("text is required");
  }

  if (voice !== undefined) {
    if (typeof voice !== "string") {
      throw new Error("voice must be a string");
    }

    if (voice.trim().length === 0) {
      throw new Error("voice must be a non-empty string");
    }
  }

  return {
    text: text.trim(),
    voice: typeof voice === "string" ? voice.trim() : voice,
  };
}

async function primeAudioStream(stream: ReadableStream<Uint8Array>) {
  const reader = stream.getReader();
  const firstChunk = await reader.read();
  let firstChunkConsumed = false;

  return new ReadableStream<Uint8Array>({
    async pull(controller) {
      try {
        if (!firstChunkConsumed) {
          firstChunkConsumed = true;

          if (firstChunk.done) {
            controller.close();
            return;
          }

          controller.enqueue(firstChunk.value);
          return;
        }

        const chunk = await reader.read();
        if (chunk.done) {
          controller.close();
          return;
        }

        controller.enqueue(chunk.value);
      } catch (error) {
        controller.error(error);
      }
    },
    async cancel(reason) {
      await reader.cancel(reason);
    },
  });
}

export async function handleTts(request: Request) {
  const contentType = request.headers.get("content-type") ?? "";
  if (!isJsonContentType(contentType)) {
    return errorResponse(
      400,
      "INVALID_CONTENT_TYPE",
      "content-type must be application/json"
    );
  }

  let body: unknown;

  try {
    body = await request.json();
  } catch {
    return errorResponse(
      400,
      "INVALID_REQUEST",
      "request body must be valid json"
    );
  }

  let parsed: ReturnType<typeof parseBody>;

  try {
    parsed = parseBody(body);
  } catch (error) {
    return errorResponse(
      400,
      "INVALID_REQUEST",
      error instanceof Error ? error.message : "request body must be valid json"
    );
  }

  try {
    const stream = await createAudioStream(parsed);
    const primedStream = await primeAudioStream(stream);

    return new Response(primedStream, {
      status: 200,
      headers: {
        ...CORS_HEADERS,
        "Content-Type": "audio/mpeg",
      },
    });
  } catch (error) {
    console.error("tts synthesis failed", error);
    return errorResponse(502, "TTS_UPSTREAM_ERROR", "failed to synthesize audio");
  }
}

import { json } from "../lib/http";
import { handleTts } from "./tts";

type Probe = {
  voice: string;
  text: string;
};

type ProbeResult = {
  voice: string;
  ok: boolean;
  status: number;
  contentType: string;
  bytes: number;
  durationMs: number;
  error?: string;
};

const DEFAULT_PROBES: Probe[] = [
  { voice: "en-US-AvaMultilingualNeural", text: "health check" },
  { voice: "zh-CN-XiaoxiaoNeural", text: "健康检查" },
];

const PROBE_TIMEOUT_MS = 15_000;

async function runProbe(
  url: URL,
  { voice, text }: Probe,
  timeoutMs: number
): Promise<ProbeResult> {
  const startedAt = Date.now();
  const result: ProbeResult = {
    voice,
    ok: false,
    status: 0,
    contentType: "",
    bytes: 0,
    durationMs: 0,
  };
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(
      () => reject(new Error(`timed out after ${timeoutMs} ms`)),
      timeoutMs
    );
  });

  try {
    // Run the same handler as POST /tts so the probe covers request
    // parsing, the upstream WebSocket and the audio stream.
    const response = await Promise.race([
      handleTts(
        new Request(new URL("/tts", url), {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ text, voice }),
        })
      ),
      timeout,
    ]);
    result.status = response.status;
    result.contentType = response.headers.get("content-type") ?? "";
    result.bytes = (
      await Promise.race([response.arrayBuffer(), timeout])
    ).byteLength;
    result.ok =
      result.status === 200 &&
      result.contentType.startsWith("audio/mpeg") &&
      result.bytes > 0;
  } catch (error) {
    result.error = error instanceof Error ? error.message : String(error);
  } finally {
    clearTimeout(timer);
  }

  result.durationMs = Date.now() - startedAt;

  if (!result.ok) {
    console.error("tts health probe failed", result);
  }

  return result;
}

export async function handleTtsHealth(
  request: Request,
  timeoutMs = PROBE_TIMEOUT_MS
) {
  const url = new URL(request.url);
  const voice = url.searchParams.get("voice")?.trim();
  const probes = voice ? [{ voice, text: "health check" }] : DEFAULT_PROBES;
  const checks = await Promise.all(
    probes.map((probe) => runProbe(url, probe, timeoutMs))
  );
  const ok = checks.every((check) => check.ok);

  return json(
    { ok, checks },
    {
      status: ok ? 200 : 503,
      headers: { "Cache-Control": "no-store" },
    }
  );
}

